#include <iostream>
#include <string>
#include <vector>

/* A bimodal predictor: a direct-mapped table of two-bit saturating
   counters, indexed by the low bits of the branch address. */
int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    unsigned long long entries = 0;
    if (!(std::cin >> entries)) return 0;
    /* Every counter starts weakly not-taken. */
    std::vector<int> table(entries, 1);

    const unsigned long long mask = entries - 1;

    unsigned long long seen = 0, wrong = 0;
    std::string pcText, outcome;
    while (std::cin >> pcText >> outcome) {
        const unsigned long long pc = std::stoull(pcText, nullptr, 16);
        const bool taken = (outcome == "T");
        const unsigned long long i = (pc >> 2) & mask;

        const bool predict = table[i] >= 2;
        if (predict != taken) ++wrong;
        ++seen;

        if (taken) { if (table[i] < 3) ++table[i]; }
        else       { if (table[i] > 0) --table[i]; }
    }

    std::cout << "branches " << seen << '\n';
    std::cout << "mispredicts " << wrong << '\n';
    std::cout << "table";
    for (unsigned long long i = 0; i < entries; ++i) std::cout << ' ' << table[i];
    std::cout << '\n';
    return 0;
}
